#!/usr/bin/env python3
"""Fit the seven-grade flux polarization to a hyperbolic orientation law."""
import json,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];src=json.loads((ROOT/'research/nima/results/phase-boundary-biconvolution-rule.json').read_text());rows=src['transitions'];xs=[r['delta'] for r in rows];ys=[math.atanh(r['orientation']) for r in rows];N=len(xs);sx=sum(xs);sy=sum(ys);sxx=sum(x*x for x in xs);sxy=sum(x*y for x,y in zip(xs,ys));a=(N*sxy-sx*sy)/(N*sxx-sx*sx);b=(sy-a*sx)/N;pred=[math.tanh(a*x+b) for x in xs];res=[p-r['orientation'] for p,r in zip(pred,rows)];table=[{'delta':x,'observed':r['orientation'],'predicted_tanh':p,'residual':e,'rapidity':y} for x,r,p,e,y in zip(xs,rows,pred,res,ys)];maxerr=max(map(abs,res));checks={'rapidity_strictly_orders_grade':all(u<v for u,v in zip(ys,ys[1:])),'positive_slope':a>0,'single_affine_rapidity_is_not_exact':maxerr>0.05}
out={'schema':'marici.nima.phase-boundary-orientation-law.v1','candidate':'omega=tanh(a*delta+b)','a':a,'b':b,'zero_crossing_delta':-b/a,'max_abs_orientation_residual':maxerr,'rows':table,'checks':checks,'passed':all(checks.values()),'conclusion':'Degree shift is an ordered rapidity coordinate, but one affine tanh law does not fit all representatives; base degree and lower-order kinematics remain visible.'};p=ROOT/'research/nima/results/phase-boundary-orientation-law.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
